:root {
  --ink: #2a1235;
  --ink-soft: #664f70;
  --lavender: #f1ebff;
  --paper: #fffdf8;
  --white: #ffffff;
  --tomato: #ff584c;
  --tomato-dark: #d93732;
  --berry: #7a3aed;
  --berry-dark: #4e1d9b;
  --butter: #ffd95a;
  --mint: #8fe0c0;
  --line: rgba(42, 18, 53, 0.16);
  --shadow: 0 24px 70px rgba(67, 35, 92, 0.16);
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html {
  background: var(--lavender);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--ink);
  background:
    radial-gradient(circle at 5% 0%, rgba(255, 217, 90, 0.42), transparent 25rem),
    radial-gradient(circle at 97% 32%, rgba(143, 224, 192, 0.42), transparent 28rem),
    var(--lavender);
  font-family: "Avenir Next", Avenir, "Segoe UI", sans-serif;
  min-height: 100vh;
}

button,
input {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
a:focus-visible,
input:focus-visible {
  outline: 3px solid var(--butter);
  outline-offset: 3px;
}

button {
  color: inherit;
}

.app-shell {
  width: min(1480px, 100%);
  min-height: 100vh;
  margin: 0 auto;
  padding: 0 clamp(20px, 4vw, 64px);
  overflow: hidden;
}

.topbar {
  height: 88px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  border-bottom: 1px solid var(--line);
}

.wordmark {
  width: max-content;
  border: 0;
  padding: 0;
  background: transparent;
  font-family: "Arial Rounded MT Bold", "Trebuchet MS", sans-serif;
  font-size: 1.06rem;
  font-weight: 800;
  letter-spacing: -0.04em;
  cursor: pointer;
}

.wordmark-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  margin-right: 8px;
  border-radius: 50% 50% 45% 55%;
  background: var(--tomato);
  box-shadow: 6px -4px 0 -3px var(--berry);
  transform: rotate(-18deg);
}

.topbar-note {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.tiny-button {
  justify-self: end;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.48);
  padding: 8px 14px;
  font-size: 0.76rem;
  font-weight: 700;
  cursor: pointer;
}

.setup-layout {
  display: grid;
  grid-template-columns: minmax(300px, 0.9fr) minmax(520px, 1.1fr);
  gap: clamp(48px, 8vw, 132px);
  align-items: start;
  padding: clamp(54px, 8vw, 112px) 0 100px;
}

.hero-copy {
  position: sticky;
  top: 42px;
  padding-top: 34px;
}

.eyebrow {
  margin: 0 0 18px;
  color: var(--berry-dark);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.eyebrow span {
