:root {
  --room: #2b1f27;
  --room-light: #3b2b35;
  --room-deep: #1c1318;
  --lamp: #f4eadb;
  --lamp-bright: #f9f2e6;
  --lamp-deep: #e6d8c3;
  --ink: #2a1e23;
  --ink-2: #6f6066;
  --ink-3: #9d8f95;
  --on-room: #f4eadb;
  --on-room-2: rgba(244, 234, 219, 0.64);
  --on-room-3: rgba(244, 234, 219, 0.38);
  --veil: rgba(244, 234, 219, 0.08);
  --veil-2: rgba(244, 234, 219, 0.14);
  --chili: #d8412f;
  --chili-deep: #b7321f;
  --p1: #d98c9b;
  --p2: #e0a472;
  --p3: #9db58b;
  --p4: #8dafc7;
  --p5: #b39ac9;
  --p6: #d2b15a;
  --p7: #7fb3ae;
  --p8: #c98a78;
  --r-card: 28px;
  --r-control: 14px;
  --shadow-card:
    0 34px 60px -24px rgba(0, 0, 0, 0.6),
    0 0 110px -20px rgba(244, 234, 219, 0.14);
  --shadow-soft: 0 14px 30px -18px rgba(0, 0, 0, 0.5);
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html {
  background: var(--room-deep);
}

body {
  margin: 0;
  min-height: 100dvh;
  color: var(--on-room);
  background:
    radial-gradient(ellipse 130% 60% at 50% -12%, var(--room-light) 0%, var(--room) 48%, var(--room-deep) 100%)
      fixed;
  font-family: var(--font-body), "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  letter-spacing: -0.01em;
}

p {
  margin: 0;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:disabled {
  cursor: default;
  opacity: 0.55;
}

a {
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

:focus-visible {
  outline: 2px solid var(--lamp);
  outline-offset: 3px;
}

.card :focus-visible,
.card-front :focus-visible {
  outline-color: var(--chili);
}

/* Shell */

.shell {
  width: min(440px, 100%);
  min-height: 100dvh;
  margin: 0 auto;
  padding: 0 16px calc(20px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
}

.topbar {
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.wordmark {
  border: 0;
  padding: 0;
  background: none;
  font-family: var(--font-display), Georgia, serif;
  font-size: 1.15rem;
  color: var(--on-room);
}

.text-button {
  border: 0;
  padding: 8px 2px;
  background: none;
  font-size: 0.9rem;
  color: var(--on-room-2);
}

.text-button:hover {
  color: var(--on-room);
}

.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.screen-head {
  padding: 8px 0 26px;
}

.screen-head h1 {
  font-size: clamp(1.8rem, 7.6vw, 2.15rem);
  line-height: 1.12;
  color: var(--on-room);
}

.screen-head p {
  margin-top: 10px;
  color: var(--on-room-2);
  max-width: 34ch;
}

.steps {
  display: flex;
  gap: 6px;
  margin-bottom: 26px;
}

.steps span {
  flex: 1;
  height: 3px;
  border-radius: 2px;
  background: var(--on-room-3);
  transition: background 0.3s;
}

.steps span.done {
  background: var(--on-room);
}

.group {
  border: 0;
  margin: 0 0 26px;
  padding: 0;
  min-width: 0;
}

.group-title {
  margin: 0 0 12px;
  color: var(--on-room-2);
  font-size: 0.95rem;
}

.step-nav {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding-top: 18px;
}

.step-nav .primary {
  flex: 1;
}

/* Controls on the room */

.primary,
.secondary {
  height: 54px;
  padding: 0 24px;
  border: 0;
  border-radius: 999px;
  font-size: 1.02rem;
  font-weight: 600;
  transition: transform 0.15s, background 0.2s;
}

.primary {
  background: var(--chili);
  color: var(--lamp-bright);
}

.primary:hover:not(:disabled) {
  background: var(--chili-deep);
}

.primary:active:not(:disabled) {
  transform: scale(0.985);
}

.primary.block {
  width: 100%;
}

.secondary {
  background: var(--veil);
  color: var(--on-room);
}

.secondary:hover:not(:disabled) {
  background: var(--veil-2);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  padding: 10px 16px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--veil);
  color: var(--on-room);
  font-size: 0.95rem;
  transition: background 0.2s, color 0.2s;
}

.chip:hover {
  background: var(--veil-2);
}

.chip.on {
  background: var(--lamp);
  color: var(--ink);
}

.add-row {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.field {
  width: 100%;
  min-width: 0;
  height: 48px;
  padding: 0 16px;
  border: 1px solid var(--veil-2);
  border-radius: var(--r-control);
  background: var(--veil);
  color: var(--on-room);
}

.field::placeholder {
  color: var(--on-room-3);
}

.field:focus {
  outline: none;
  border-color: var(--on-room-2);
}

.add-row .secondary {
  height: 48px;
  padding: 0 18px;
  flex-shrink: 0;
}

.count-row {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 6px;
}

.count-row button {
  aspect-ratio: 1;
  border: 0;
  border-radius: 999px;
  background: var(--veil);
  color: var(--on-room);
  font-weight: 500;
  transition: background 0.2s, color 0.2s;
}

.count-row button:hover {
  background: var(--veil-2);
}

.count-row button.on {
  background: var(--lamp);
  color: var(--ink);
}

.names {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 16px;
}

.names label {
  display: grid;
  gap: 5px;
  font-size: 0.8rem;
  color: var(--on-room-2);
}

.names label:has(.person-dot) {
  grid-template-columns: auto 1fr;
}

.names .field {
  height: 44px;
}

.tiles {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tile {
  padding: 14px 16px;
  border: 0;
  border-radius: var(--r-control);
  background: var(--veil);
  color: var(--on-room);
  text-align: left;
  display: grid;
  gap: 3px;
  transition: background 0.2s, color 0.2s;
}

.tile:hover {
  background: var(--veil-2);
}

.tile strong {
  font-weight: 600;
  font-size: 0.98rem;
}

.tile small {
  font-size: 0.82rem;
  color: var(--on-room-2);
}

.tile.on {
  background: var(--lamp);
  color: var(--ink);
}

.tile.on small {
  color: var(--ink-2);
}

.segmented {
  display: flex;
  padding: 4px;
  border-radius: 999px;
  background: var(--veil);
}

.segmented button {
  flex: 1;
  height: 40px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--on-room-2);
  font-size: 0.92rem;
  font-weight: 500;
  transition: background 0.2s, color 0.2s;
}

.segmented button.on {
  background: var(--lamp);
  color: var(--ink);
}

.pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.reveal {
  margin-top: 8px;
}

.reveal summary {
  list-style: none;
  cursor: pointer;
  color: var(--on-room-2);
  font-size: 0.92rem;
  padding: 10px 0;
  width: max-content;
}

.reveal summary::-webkit-details-marker {
  display: none;
}

.reveal summary:hover {
  color: var(--on-room);
}

.reveal .add-row {
  margin-top: 4px;
}

.reveal .field {
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.help {
  margin-top: 12px;
  font-size: 0.86rem;
  color: var(--on-room-3);
}

.location {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--r-control);
  background: var(--veil);
}

.location strong {
  display: block;
  font-weight: 600;
  font-size: 0.95rem;
}

.location span {
  display: block;
  font-size: 0.84rem;
  color: var(--on-room-2);
}

.location button {
  flex-shrink: 0;
  height: 40px;
  padding: 0 16px;
  border: 0;
  border-radius: 999px;
  background: var(--lamp);
  color: var(--ink);
  font-size: 0.9rem;
  font-weight: 600;
}

.location button.ready {
  background: var(--veil-2);
  color: var(--on-room);
}

.error {
  margin: 0 0 14px;
  padding: 12px 14px;
  border-radius: var(--r-control);
  background: rgba(216, 65, 47, 0.16);
  color: #f7c9c1;
  font-size: 0.92rem;
}

/* People */

.person-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: var(--person, var(--lamp));
  flex-shrink: 0;
}

.people {
  display: flex;
  gap: 6px;
}

.people span {
  width: 12px;
  height: 12px;
  border-radius: 999px;
  background: var(--person, var(--lamp));
  opacity: 0.4;
  transition: opacity 0.2s, box-shadow 0.2s;
}

.people span.done {
  opacity: 1;
}

.people span.current {
  opacity: 1;
  box-shadow: 0 0 0 3px var(--room), 0 0 0 4.5px var(--person, var(--lamp));
}

.roster {
  display: grid;
  gap: 4px;
  margin-bottom: 26px;
}

.roster-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: var(--r-control);
  background: var(--veil);
}

.roster-row .person-dot {
  width: 12px;
  height: 12px;
}

.roster-row strong {
  display: block;
  font-weight: 600;
  font-size: 0.98rem;
}

.roster-row small {
  display: block;
  font-size: 0.84rem;
  color: var(--on-room-2);
}

.roster-row > div {
  flex: 1;
  min-width: 0;
}

.roster-row .status {
  color: var(--on-room-2);
  font-size: 0.9rem;
}

.roster-row .status.done {
  color: var(--p3);
}

.roster-row .secondary {
  height: 38px;
  padding: 0 14px;
  font-size: 0.88rem;
}

.room-code {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 26px;
  padding: 20px 22px;
  border-radius: var(--r-card);
  background: var(--veil);
}

.room-code small {
  display: block;
  color: var(--on-room-2);
  font-size: 0.86rem;
}

.room-code strong {
  display: block;
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  font-size: 2rem;
  letter-spacing: 0.18em;
  line-height: 1.1;
}

.room-code .secondary {
  flex-shrink: 0;
  height: 44px;
  padding: 0 16px;
  font-size: 0.9rem;
}

/* Deck */

.deck-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 4px 14px;
  color: var(--on-room-2);
  font-size: 0.92rem;
}

.deck-top strong {
  color: var(--on-room);
  font-weight: 600;
}

.progress {
  height: 3px;
  border-radius: 2px;
  background: var(--veil-2);
  overflow: hidden;
  margin: 0 4px 22px;
}

.progress span {
  display: block;
  height: 100%;
  border-radius: 2px;
  background: var(--lamp);
  transition: width 0.3s ease;
}

.stage {
  position: relative;
  flex: 1;
  min-height: 500px;
}

.card {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 26px 24px 22px;
  border-radius: var(--r-card);
  background:
    radial-gradient(ellipse 90% 50% at 50% 0%, var(--lamp-bright) 0%, transparent 70%),
    linear-gradient(180deg, var(--lamp) 0%, var(--lamp-deep) 100%);
  color: var(--ink);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.card.behind {
  transform: scale(0.94) translateY(16px);
  opacity: 0.5;
  box-shadow: none;
}

.card.front {
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  cursor: grab;
  transition: transform 0.25s ease;
}

.card.front.dragging {
  cursor: grabbing;
  transition: none;
}

.card-kicker {
  display: flex;
  justify-content: space-between;
  color: var(--ink-2);
  font-size: 0.92rem;
}

.card h2 {
  margin: 20px 0 12px;
  font-size: clamp(2.05rem, 9.5vw, 2.6rem);
  line-height: 1.04;
}

.card .meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  color: var(--ink-2);
  font-size: 0.94rem;
}

.card .meta strong {
  color: var(--ink);
  font-weight: 600;
}

.card .why {
  margin-top: 22px;
  font-size: 1.05rem;
  line-height: 1.5;
  max-width: 30ch;
}

.order {
  margin-top: auto;
  padding-top: 22px;
}

.order small {
  display: block;
  margin-bottom: 8px;
  color: var(--ink-2);
  font-size: 0.86rem;
}

.order ul {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.order li {
  padding: 7px 12px;
  border-radius: 999px;
  background: rgba(42, 30, 35, 0.07);
  font-size: 0.9rem;
  font-weight: 500;
}

.card-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 18px;
  color: var(--ink-3);
  font-size: 0.84rem;
}

.card-foot .fit {
  color: var(--ink-2);
}

.card-foot .fit strong {
  color: var(--ink);
  font-weight: 600;
}

.stamp {
  position: absolute;
  top: 22px;
  padding: 6px 14px;
  border: 2px solid currentColor;
  border-radius: 10px;
  font-family: var(--font-display), Georgia, serif;
  font-size: 1.35rem;
  pointer-events: none;
}

.stamp.yes {
  left: 22px;
  color: var(--p3);
  transform: rotate(-10deg);
}

.stamp.no {
  right: 22px;
  color: var(--chili);
  transform: rotate(10deg);
}

.stamp.love {
  left: 50%;
  color: var(--chili);
  transform: translateX(-50%) rotate(-4deg);
}

.actions {
  display: flex;
  justify-content: center;
  align-items: flex-end;
  gap: 22px;
  padding: 26px 0 8px;
}

.actions button {
  display: grid;
  justify-items: center;
  gap: 8px;
  border: 0;
  padding: 0;
  background: none;
  color: var(--on-room-2);
  font-size: 0.8rem;
}

.actions button span {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  border-radius: 999px;
  background: var(--veil-2);
  color: var(--on-room);
  font-size: 1.5rem;
  line-height: 1;
  transition: transform 0.15s, background 0.2s;
}

.actions button:hover:not(:disabled) span {
  transform: translateY(-2px);
}

.actions .love span {
  width: 70px;
  height: 70px;
  background: var(--chili);
  color: var(--lamp-bright);
  font-size: 1.6rem;
}

.actions .like span {
  background: var(--lamp);
  color: var(--ink);
}

.hint {
  text-align: center;
  color: var(--on-room-3);
  font-size: 0.84rem;
}

.hint + .hint {
  margin-top: 4px;
}

.handoff {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-bottom: 60px;
}

.handoff p {
  color: var(--on-room-2);
}

.handoff h1 {
  font-size: clamp(2.6rem, 12vw, 3.4rem);
  line-height: 1.05;
  margin: 6px 0 30px;
}

/* Result and fallback */

.panel {
  padding: 26px 24px 24px;
  border-radius: var(--r-card);
  background:
    radial-gradient(ellipse 90% 50% at 50% 0%, var(--lamp-bright) 0%, transparent 70%),
    linear-gradient(180deg, var(--lamp) 0%, var(--lamp-deep) 100%);
  color: var(--ink);
  box-shadow: var(--shadow-card);
}

.panel .lead {
  color: var(--ink-2);
  font-size: 0.95rem;
}

.panel h2 {
  margin: 10px 0 14px;
  font-size: clamp(2rem, 9vw, 2.5rem);
  line-height: 1.05;
}

.supporters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  margin-bottom: 20px;
  font-size: 0.95rem;
}

.supporters span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.facts {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 22px;
}

.facts div {
  padding: 12px 14px;
  border-radius: var(--r-control);
  background: rgba(42, 30, 35, 0.06);
}

.facts small {
  display: block;
  color: var(--ink-2);
  font-size: 0.8rem;
}

.facts strong {
  display: block;
  font-weight: 600;
  font-size: 1rem;
}

.panel .order {
  margin-top: 0;
  padding-top: 0;
}

.panel .note {
  margin-top: 18px;
  color: var(--ink-2);
  font-size: 0.86rem;
  line-height: 1.5;
}

.links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
}

.links a {
  flex: 1;
  display: grid;
  place-items: center;
  height: 48px;
  padding: 0 16px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--lamp);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
}

.links span {
  color: var(--ink-3);
  font-size: 0.86rem;
}

.after {
  display: flex;
  justify-content: center;
  padding: 24px 0 8px;
}

.plate-items {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 16px;
  margin: 0 0 20px;
  padding: 0;
  list-style: none;
}

.plate-items li {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-weight: 500;
  line-height: 1.35;
}

.plate-items li::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--chili);
  flex-shrink: 0;
  transform: translateY(-1px);
}

.panel .instructions {
  line-height: 1.55;
}

.waiting {
  flex: 1;
  justify-content: center;
  padding-bottom: 60px;
}

.waiting .roster {
  margin-top: 8px;
}

footer {
  padding: 28px 4px 0;
  text-align: center;
  color: var(--on-room-3);
  font-size: 0.82rem;
}

@media (min-width: 720px) {
  .shell {
    width: min(460px, 100%);
  }

  .topbar {
    height: 80px;
  }

  .stage {
    min-height: 540px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
  }
}

toolu_01BQEXdxoBKw7krwemgPE3H8.content:
:root {
  --room: #2b1f27;
  --room-light: #3b2b35;
  --room-deep: #1c1318;
  --lamp: #f4eadb;
  --lamp-bright: #f9f2e6;
  --lamp-deep: #e6d8c3;
  --ink: #2a1e23;
  --ink-2: #6f6066;
  --ink-3: #9d8f95;
  --on-room: #f4eadb;
  --on-room-2: rgba(244, 234, 219, 0.64);
  --on-room-3: rgba(244, 234, 219, 0.38);
  --veil: rgba(244, 234, 219, 0.08);
  --veil-2: rgba(244, 234, 219, 0.14);
  --chili: #d8412f;
  --chili-deep: #b7321f;
  --p1: #d98c9b;
  --p2: #e0a472;
  --p3: #9db58b;
  --p4: #8dafc7;
  --p5: #b39ac9;
  --p6: #d2b15a;
  --p7: #7fb3ae;
  --p8: #c98a78;
  --r-card: 28px;
  --r-control: 14px;
  --shadow-card:
    0 34px 60px -24px rgba(0, 0, 0, 0.6),
    0 0 110px -20px rgba(244, 234, 219, 0.14);
  --shadow-soft: 0 14px 30px -18px rgba(0, 0, 0, 0.5);
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html {
  background: var(--room-deep);
}

body {
  margin: 0;
  min-height: 100dvh;
  color: var(--on-room);
  background:
    radial-gradient(ellipse 130% 60% at 50% -12%, var(--room-light) 0%, var(--room) 48%, var(--room-deep) 100%)
      fixed;
  font-family: var(--font-body), "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  letter-spacing: -0.01em;
}

p {
  margin: 0;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:disabled {
  cursor: default;
  opacity: 0.55;
}

a {
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

:focus-visible {
  outline: 2px solid var(--lamp);
  outline-offset: 3px;
}

.card :focus-visible,
.card-front :focus-visible {
  outline-color: var(--chili);
}

/* Shell */

.shell {
  width: min(440px, 100%);
  min-height: 100dvh;
  margin: 0 auto;
  padding: 0 16px calc(20px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
}

.topbar {
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.wordmark {
  border: 0;
  padding: 0;
  background: none;
  font-family: var(--font-display), Georgia, serif;
  font-size: 1.15rem;
  color: var(--on-room);
}

.text-button {
  border: 0;
  padding: 8px 2px;
  background: none;
  font-size: 0.9rem;
  color: var(--on-room-2);
}

.text-button:hover {
  color: var(--on-room);
}

.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.screen-head {
  padding: 8px 0 26px;
}

.screen-head h1 {
  font-size: clamp(1.8rem, 7.6vw, 2.15rem);
  line-height: 1.12;
  color: var(--on-room);
}

.screen-head p {
  margin-top: 10px;
  color: var(--on-room-2);
  max-width: 34ch;
}

.steps {
  display: flex;
  gap: 6px;
  margin-bottom: 26px;
}

.steps span {
  flex: 1;
  height: 3px;
  border-radius: 2px;
  background: var(--on-room-3);
  transition: background 0.3s;
}

.steps span.done {
  background: var(--on-room);
}

.group {
  border: 0;
  margin: 0 0 26px;
  padding: 0;
  min-width: 0;
}

.group-title {
  margin: 0 0 12px;
  color: var(--on-room-2);
  font-size: 0.95rem;
}

.step-nav {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding-top: 18px;
}

.step-nav .primary {
  flex: 1;
}

/* Controls on the room */

.primary,
.secondary {
  height: 54px;
  padding: 0 24px;
  border: 0;
  border-radius: 999px;
  font-size: 1.02rem;
  font-weight: 600;
  transition: transform 0.15s, background 0.2s;
}

.primary {
  background: var(--chili);
  color: var(--lamp-bright);
}

.primary:hover:not(:disabled) {
  background: var(--chili-deep);
}

.primary:active:not(:disabled) {
  transform: scale(0.985);
}

.primary.block {
  width: 100%;
}

.secondary {
  background: var(--veil);
  color: var(--on-room);
}

.secondary:hover:not(:disabled) {
  background: var(--veil-2);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  padding: 10px 16px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--veil);
  color: var(--on-room);
  font-size: 0.95rem;
  transition: background 0.2s, color 0.2s;
}

.chip:hover {
  background: var(--veil-2);
}

.chip.on {
  background: var(--lamp);
  color: var(--ink);
}

.add-row {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.field {
  width: 100%;
  min-width: 0;
  height: 48px;
  padding: 0 16px;
  border: 1px solid var(--veil-2);
  border-radius: var(--r-control);
  background: var(--veil);
  color: var(--on-room);
}

.field::placeholder {
  color: var(--on-room-3);
}

.field:focus {
  outline: none;
  border-color: var(--on-room-2);
}

.add-row .secondary {
  height: 48px;
  padding: 0 18px;
  flex-shrink: 0;
}

.count-row {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 6px;
}

.count-row button {
  aspect-ratio: 1;
  border: 0;
  border-radius: 999px;
  background: var(--veil);
  color: var(--on-room);
  font-weight: 500;
  transition: background 0.2s, color 0.2s;
}

.count-row button:hover {
  background: var(--veil-2);
}

.count-row button.on {
  background: var(--lamp);
  color: var(--ink);
}

.names {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 16px;
}

.names label {
  display: grid;
  gap: 5px;
  font-size: 0.8rem;
  color: var(--on-room-2);
}

.names label:has(.person-dot) {
  grid-template-columns: auto 1fr;
}

.names .field {
  height: 44px;
}

.tiles {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tile {
  padding: 14px 16px;
  border: 0;
  border-radius: var(--r-control);
  background: var(--veil);
  color: var(--on-room);
  text-align: left;
  display: grid;
  gap: 3px;
  transition: background 0.2s, color 0.2s;
}

.tile:hover {
  background: var(--veil-2);
}

.tile strong {
  font-weight: 600;
  font-size: 0.98rem;
}

.tile small {
  font-size: 0.82rem;
  color: var(--on-room-2);
}

.tile.on {
  background: var(--lamp);
  color: var(--ink);
}

.tile.on small {
  color: var(--ink-2);
}

.segmented {
  display: flex;
  padding: 4px;
  border-radius: 999px;
  background: var(--veil);
}

.segmented button {
  flex: 1;
  height: 40px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--on-room-2);
  font-size: 0.92rem;
  font-weight: 500;
  transition: background 0.2s, color 0.2s;
}

.segmented button.on {
  background: var(--lamp);
  color: var(--ink);
}

.pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.reveal {
  margin-top: 8px;
}

.reveal summary {
  list-style: none;
  cursor: pointer;
  color: var(--on-room-2);
  font-size: 0.92rem;
  padding: 10px 0;
  width: max-content;
}

.reveal summary::-webkit-details-marker {
  display: none;
}

.reveal summary:hover {
  color: var(--on-room);
}

.reveal .add-row {
  margin-top: 4px;
}

.reveal .field {
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.help {
  margin-top: 12px;
  font-size: 0.86rem;
  color: var(--on-room-3);
}

.location {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--r-control);
  background: var(--veil);
}

.location strong {
  display: block;
  font-weight: 600;
  font-size: 0.95rem;
}

.location span {
  display: block;
  font-size: 0.84rem;
  color: var(--on-room-2);
}

.location button {
  flex-shrink: 0;
  height: 40px;
  padding: 0 16px;
  border: 0;
  border-radius: 999px;
  background: var(--lamp);
  color: var(--ink);
  font-size: 0.9rem;
  font-weight: 600;
}

.location button.ready {
  background: var(--veil-2);
  color: var(--on-room);
}

.error {
  margin: 0 0 14px;
  padding: 12px 14px;
  border-radius: var(--r-control);
  background: rgba(216, 65, 47, 0.16);
  color: #f7c9c1;
  font-size: 0.92rem;
}

/* People */

.person-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: var(--person, var(--lamp));
  flex-shrink: 0;
}

.people {
  display: flex;
  gap: 6px;
}

.people span {
  width: 12px;
  height: 12px;
  border-radius: 999px;
  background: var(--person, var(--lamp));
  opacity: 0.4;
  transition: opacity 0.2s, box-shadow 0.2s;
}

.people span.done {
  opacity: 1;
}

.people span.current {
  opacity: 1;
  box-shadow: 0 0 0 3px var(--room), 0 0 0 4.5px var(--person, var(--lamp));
}

.roster {
  display: grid;
  gap: 4px;
  margin-bottom: 26px;
}

.roster-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: var(--r-control);
  background: var(--veil);
}

.roster-row .person-dot {
  width: 12px;
  height: 12px;
}

.roster-row strong {
  display: block;
  font-weight: 600;
  font-size: 0.98rem;
}

.roster-row small {
  display: block;
  font-size: 0.84rem;
  color: var(--on-room-2);
}

.roster-row > div {
  flex: 1;
  min-width: 0;
}

.roster-row .status {
  color: var(--on-room-2);
  font-size: 0.9rem;
}

.roster-row .status.done {
  color: var(--p3);
}

.roster-row .secondary {
  height: 38px;
  padding: 0 14px;
  font-size: 0.88rem;
}

.room-code {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 26px;
  padding: 20px 22px;
  border-radius: var(--r-card);
  background: var(--veil);
}

.room-code small {
  display: block;
  color: var(--on-room-2);
  font-size: 0.86rem;
}

.room-code strong {
  display: block;
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  font-size: 2rem;
  letter-spacing: 0.18em;
  line-height: 1.1;
}

.room-code .secondary {
  flex-shrink: 0;
  height: 44px;
  padding: 0 16px;
  font-size: 0.9rem;
}

/* Deck */

.deck-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 4px 14px;
  color: var(--on-room-2);
  font-size: 0.92rem;
}

.deck-top strong {
  color: var(--on-room);
  font-weight: 600;
}

.progress {
  height: 3px;
  border-radius: 2px;
  background: var(--veil-2);
  overflow: hidden;
  margin: 0 4px 22px;
}

.progress span {
  display: block;
  height: 100%;
  border-radius: 2px;
  background: var(--lamp);
  transition: width 0.3s ease;
}

.stage {
  position: relative;
  flex: 1;
  min-height: 500px;
}

.card {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 26px 24px 22px;
  border-radius: var(--r-card);
  background:
    radial-gradient(ellipse 90% 50% at 50% 0%, var(--lamp-bright) 0%, transparent 70%),
    linear-gradient(180deg, var(--lamp) 0%, var(--lamp-deep) 100%);
  color: var(--ink);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.card.behind {
  transform: scale(0.94) translateY(16px);
  opacity: 0.5;
  box-shadow: none;
}

.card.front {
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  cursor: grab;
  transition: transform 0.25s ease;
}

.card.front.dragging {
  cursor: grabbing;
  transition: none;
}

.card-kicker {
  display: flex;
  justify-content: space-between;
  color: var(--ink-2);
  font-size: 0.92rem;
}

.card h2 {
  margin: 20px 0 12px;
  font-size: clamp(2.05rem, 9.5vw, 2.6rem);
  line-height: 1.04;
}

.card .meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  color: var(--ink-2);
  font-size: 0.94rem;
}

.card .meta strong {
  color: var(--ink);
  font-weight: 600;
}

.card .why {
  margin-top: 22px;
  font-size: 1.05rem;
  line-height: 1.5;
  max-width: 30ch;
}

.order {
  margin-top: auto;
  padding-top: 22px;
}

.order small {
  display: block;
  margin-bottom: 8px;
  color: var(--ink-2);
  font-size: 0.86rem;
}

.order ul {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.order li {
  padding: 7px 12px;
  border-radius: 999px;
  background: rgba(42, 30, 35, 0.07);
  font-size: 0.9rem;
  font-weight: 500;
}

.card-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 18px;
  color: var(--ink-3);
  font-size: 0.84rem;
}

.card-foot .fit {
  color: var(--ink-2);
}

.card-foot .fit strong {
  color: var(--ink);
  font-weight: 600;
}

.stamp {
  position: absolute;
  top: 22px;
  padding: 6px 14px;
  border: 2px solid currentColor;
  border-radius: 10px;
  font-family: var(--font-display), Georgia, serif;
  font-size: 1.35rem;
  pointer-events: none;
}

.stamp.yes {
  left: 22px;
  color: var(--p3);
  transform: rotate(-10deg);
}

.stamp.no {
  right: 22px;
  color: var(--chili);
  transform: rotate(10deg);
}

.stamp.love {
  left: 50%;
  color: var(--chili);
  transform: translateX(-50%) rotate(-4deg);
}

.actions {
  display: flex;
  justify-content: center;
  align-items: flex-end;
  gap: 22px;
  padding: 26px 0 8px;
}

.actions button {
  display: grid;
  justify-items: center;
  gap: 8px;
  border: 0;
  padding: 0;
  background: none;
  color: var(--on-room-2);
  font-size: 0.8rem;
}

.actions button span {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  border-radius: 999px;
  background: var(--veil-2);
  color: var(--on-room);
  font-size: 1.5rem;
  line-height: 1;
  transition: transform 0.15s, background 0.2s;
}

.actions button:hover:not(:disabled) span {
  transform: translateY(-2px);
}

.actions .love span {
  width: 70px;
  height: 70px;
  background: var(--chili);
  color: var(--lamp-bright);
  font-size: 1.6rem;
}

.actions .like span {
  background: var(--lamp);
  color: var(--ink);
}

.hint {
  text-align: center;
  color: var(--on-room-3);
  font-size: 0.84rem;
}

.hint + .hint {
  margin-top: 4px;
}

.handoff {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-bottom: 60px;
}

.handoff p {
  color: var(--on-room-2);
}

.handoff h1 {
  font-size: clamp(2.6rem, 12vw, 3.4rem);
  line-height: 1.05;
  margin: 6px 0 30px;
}

/* Result and fallback */

.panel {
  padding: 26px 24px 24px;
  border-radius: var(--r-card);
  background:
    radial-gradient(ellipse 90% 50% at 50% 0%, var(--lamp-bright) 0%, transparent 70%),
    linear-gradient(180deg, var(--lamp) 0%, var(--lamp-deep) 100%);
  color: var(--ink);
  box-shadow: var(--shadow-card);
}

.panel .lead {
  color: var(--ink-2);
  font-size: 0.95rem;
}

.panel h2 {
  margin: 10px 0 14px;
  font-size: clamp(2rem, 9vw, 2.5rem);
  line-height: 1.05;
}

.supporters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  margin-bottom: 20px;
  font-size: 0.95rem;
}

.supporters span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.facts {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 22px;
}

.facts div {
  padding: 12px 14px;
  border-radius: var(--r-control);
  background: rgba(42, 30, 35, 0.06);
}

.facts small {
  display: block;
  color: var(--ink-2);
  font-size: 0.8rem;
}

.facts strong {
  display: block;
  font-weight: 600;
  font-size: 1rem;
}

.panel .order {
  margin-top: 0;
  padding-top: 0;
}

.panel .note {
  margin-top: 18px;
  color: var(--ink-2);
  font-size: 0.86rem;
  line-height: 1.5;
}

.links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
}

.links a {
  flex: 1;
  display: grid;
  place-items: center;
  height: 48px;
  padding: 0 16px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--lamp);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
}

.links span {
  color: var(--ink-3);
  font-size: 0.86rem;
}

.after {
  display: flex;
  justify-content: center;
  padding: 24px 0 8px;
}

.plate-items {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 16px;
  margin: 0 0 20px;
  padding: 0;
  list-style: none;
}

.plate-items li {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-weight: 500;
  line-height: 1.35;
}

.plate-items li::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--chili);
  flex-shrink: 0;
  transform: translateY(-1px);
}

.panel .instructions {
  line-height: 1.55;
}

.waiting {
  flex: 1;
  justify-content: center;
  padding-bottom: 60px;
}

.waiting .roster {
  margin-top: 8px;
}

footer {
  padding: 28px 4px 0;
  text-align: center;
  color: var(--on-room-3);
  font-size: 0.82rem;
}

@media (min-width: 720px) {
  .shell {
    width: min(460px, 100%);
  }

  .topbar {
    height: 80px;
  }

  .stage {
    min-height: 540px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
  }
}

toolUseResult.content:
:root {
  --room: #2b1f27;
  --room-light: #3b2b35;
  --room-deep: #1c1318;
  --lamp: #f4eadb;
  --lamp-bright: #f9f2e6;
  --lamp-deep: #e6d8c3;
  --ink: #2a1e23;
  --ink-2: #6f6066;
  --ink-3: #9d8f95;
  --on-room: #f4eadb;
  --on-room-2: rgba(244, 234, 219, 0.64);
  --on-room-3: rgba(244, 234, 219, 0.38);
  --veil: rgba(244, 234, 219, 0.08);
  --veil-2: rgba(244, 234, 219, 0.14);
  --chili: #d8412f;
  --chili-deep: #b7321f;
  --p1: #d98c9b;
  --p2: #e0a472;
  --p3: #9db58b;
  --p4: #8dafc7;
  --p5: #b39ac9;
  --p6: #d2b15a;
  --p7: #7fb3ae;
  --p8: #c98a78;
  --r-card: 28px;
  --r-control: 14px;
  --shadow-card:
    0 34px 60px -24px rgba(0, 0, 0, 0.6),
    0 0 110px -20px rgba(244, 234, 219, 0.14);
  --shadow-soft: 0 14px 30px -18px rgba(0, 0, 0, 0.5);
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html {
  background: var(--room-deep);
}

body {
  margin: 0;
  min-height: 100dvh;
  color: var(--on-room);
  background:
    radial-gradient(ellipse 130% 60% at 50% -12%, var(--room-light) 0%, var(--room) 48%, var(--room-deep) 100%)
      fixed;
  font-family: var(--font-body), "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  letter-spacing: -0.01em;
}

p {
  margin: 0;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:disabled {
  cursor: default;
  opacity: 0.55;
}

a {
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

:focus-visible {
  outline: 2px solid var(--lamp);
  outline-offset: 3px;
}

.card :focus-visible,
.card-front :focus-visible {
  outline-color: var(--chili);
}

/* Shell */

.shell {
  width: min(440px, 100%);
  min-height: 100dvh;
  margin: 0 auto;
  padding: 0 16px calc(20px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
}

.topbar {
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.wordmark {
  border: 0;
  padding: 0;
  background: none;
  font-family: var(--font-display), Georgia, serif;
  font-size: 1.15rem;
  color: var(--on-room);
}

.text-button {
  border: 0;
  padding: 8px 2px;
  background: none;
  font-size: 0.9rem;
  color: var(--on-room-2);
}

.text-button:hover {
  color: var(--on-room);
}

.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.screen-head {
  padding: 8px 0 26px;
}

.screen-head h1 {
  font-size: clamp(1.8rem, 7.6vw, 2.15rem);
  line-height: 1.12;
  color: var(--on-room);
}

.screen-head p {
  margin-top: 10px;
  color: var(--on-room-2);
  max-width: 34ch;
}

.steps {
  display: flex;
  gap: 6px;
  margin-bottom: 26px;
}

.steps span {
  flex: 1;
  height: 3px;
  border-radius: 2px;
  background: var(--on-room-3);
  transition: background 0.3s;
}

.steps span.done {
  background: var(--on-room);
}

.group {
  border: 0;
  margin: 0 0 26px;
  padding: 0;
  min-width: 0;
}

.group-title {
  margin: 0 0 12px;
  color: var(--on-room-2);
  font-size: 0.95rem;
}

.step-nav {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding-top: 18px;
}

.step-nav .primary {
  flex: 1;
}

/* Controls on the room */

.primary,
.secondary {
  height: 54px;
  padding: 0 24px;
  border: 0;
  border-radius: 999px;
  font-size: 1.02rem;
  font-weight: 600;
  transition: transform 0.15s, background 0.2s;
}

.primary {
  background: var(--chili);
  color: var(--lamp-bright);
}

.primary:hover:not(:disabled) {
  background: var(--chili-deep);
}

.primary:active:not(:disabled) {
  transform: scale(0.985);
}

.primary.block {
  width: 100%;
}

.secondary {
  background: var(--veil);
  color: var(--on-room);
}

.secondary:hover:not(:disabled) {
  background: var(--veil-2);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  padding: 10px 16px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--veil);
  color: var(--on-room);
  font-size: 0.95rem;
  transition: background 0.2s, color 0.2s;
}

.chip:hover {
  background: var(--veil-2);
}

.chip.on {
  background: var(--lamp);
  color: var(--ink);
}

.add-row {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.field {
  width: 100%;
  min-width: 0;
  height: 48px;
  padding: 0 16px;
  border: 1px solid var(--veil-2);
  border-radius: var(--r-control);
  background: var(--veil);
  color: var(--on-room);
}

.field::placeholder {
  color: var(--on-room-3);
}

.field:focus {
  outline: none;
  border-color: var(--on-room-2);
}

.add-row .secondary {
  height: 48px;
  padding: 0 18px;
  flex-shrink: 0;
}

.count-row {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 6px;
}

.count-row button {
  aspect-ratio: 1;
  border: 0;
  border-radius: 999px;
  background: var(--veil);
  color: var(--on-room);
  font-weight: 500;
  transition: background 0.2s, color 0.2s;
}

.count-row button:hover {
  background: var(--veil-2);
}

.count-row button.on {
  background: var(--lamp);
  color: var(--ink);
}

.names {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 16px;
}

.names label {
  display: grid;
  gap: 5px;
  font-size: 0.8rem;
  color: var(--on-room-2);
}

.names label:has(.person-dot) {
  grid-template-columns: auto 1fr;
}

.names .field {
  height: 44px;
}

.tiles {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tile {
  padding: 14px 16px;
  border: 0;
  border-radius: var(--r-control);
  background: var(--veil);
  color: var(--on-room);
  text-align: left;
  display: grid;
  gap: 3px;
  transition: background 0.2s, color 0.2s;
}

.tile:hover {
  background: var(--veil-2);
}

.tile strong {
  font-weight: 600;
  font-size: 0.98rem;
}

.tile small {
  font-size: 0.82rem;
  color: var(--on-room-2);
}

.tile.on {
  background: var(--lamp);
  color: var(--ink);
}

.tile.on small {
  color: var(--ink-2);
}

.segmented {
  display: flex;
  padding: 4px;
  border-radius: 999px;
  background: var(--veil);
}

.segmented button {
  flex: 1;
  height: 40px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--on-room-2);
  font-size: 0.92rem;
  font-weight: 500;
  transition: background 0.2s, color 0.2s;
}

.segmented button.on {
  background: var(--lamp);
  color: var(--ink);
}

.pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.reveal {
  margin-top: 8px;
}

.reveal summary {
  list-style: none;
  cursor: pointer;
  color: var(--on-room-2);
  font-size: 0.92rem;
  padding: 10px 0;
  width: max-content;
}

.reveal summary::-webkit-details-marker {
  display: none;
}

.reveal summary:hover {
  color: var(--on-room);
}

.reveal .add-row {
  margin-top: 4px;
}

.reveal .field {
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.help {
  margin-top: 12px;
  font-size: 0.86rem;
  color: var(--on-room-3);
}

.location {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--r-control);
  background: var(--veil);
}

.location strong {
  display: block;
  font-weight: 600;
  font-size: 0.95rem;
}

.location span {
  display: block;
  font-size: 0.84rem;
  color: var(--on-room-2);
}

.location button {
  flex-shrink: 0;
  height: 40px;
  padding: 0 16px;
  border: 0;
  border-radius: 999px;
  background: var(--lamp);
  color: var(--ink);
  font-size: 0.9rem;
  font-weight: 600;
}

.location button.ready {
  background: var(--veil-2);
  color: var(--on-room);
}

.error {
  margin: 0 0 14px;
  padding: 12px 14px;
  border-radius: var(--r-control);
  background: rgba(216, 65, 47, 0.16);
  color: #f7c9c1;
  font-size: 0.92rem;
}

/* People */

.person-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: var(--person, var(--lamp));
  flex-shrink: 0;
}

.people {
  display: flex;
  gap: 6px;
}

.people span {
  width: 12px;
  height: 12px;
  border-radius: 999px;
  background: var(--person, var(--lamp));
  opacity: 0.4;
  transition: opacity 0.2s, box-shadow 0.2s;
}

.people span.done {
  opacity: 1;
}

.people span.current {
  opacity: 1;
  box-shadow: 0 0 0 3px var(--room), 0 0 0 4.5px var(--person, var(--lamp));
}

.roster {
  display: grid;
  gap: 4px;
  margin-bottom: 26px;
}

.roster-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: var(--r-control);
  background: var(--veil);
}

.roster-row .person-dot {
  width: 12px;
  height: 12px;
}

.roster-row strong {
  display: block;
  font-weight: 600;
  font-size: 0.98rem;
}

.roster-row small {
  display: block;
  font-size: 0.84rem;
  color: var(--on-room-2);
}

.roster-row > div {
  flex: 1;
  min-width: 0;
}

.roster-row .status {
