}

.deck-top strong {
  color: var(--on-room);
  font-weight: 600;
}

.progress {
  height: 3px;
  border-radius: 2px;
  background: var(--veil-2);
  overflow: hidden;
  margin: 0 4px 22px;
}

.progress span {
  display: block;
  height: 100%;
  border-radius: 2px;
  background: var(--lamp);
