}

.stage {
  position: relative;
  flex: 1;
  min-height: 500px;
}

.card {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 26px 24px 22px;
  border-radius: var(--r-card);
