  cursor: grab;
  transition: transform 0.25s ease;
}

.card.front.dragging {
  cursor: grabbing;
  transition: none;
}

.card-kicker {
  display: flex;
  justify-content: space-between;
  color: var(--ink-2);
  font-size: 0.92rem;
}

.card h2 {
  margin: 20px 0 12px;
  font-size: clamp(2.05rem, 9.5vw, 2.6rem);
  line-height: 1.04;
}

.card .meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  color: var(--ink-2);
  font-size: 0.94rem;
}

.card .meta strong {
  color: var(--ink);
  font-weight: 600;
}

.card .why {
  margin-top: 22px;
  font-size: 1.05rem;
  line-height: 1.5;
  max-width: 30ch;
}

.order {
  margin-top: auto;
  padding-top: 22px;
}

.order small {
  display: block;
  margin-bottom: 8px;
  color: var(--ink-2);
  font-size: 0.86rem;
}

.order ul {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.order li {
  padding: 7px 12px;
  border-radius: 999px;
  background: rgba(42, 30, 35, 0.07);
  font-size: 0.9rem;
  font-weight: 500;
}

.card-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 18px;
  color: var(--ink-3);
