}

.actions .like span {
  background: var(--lamp);
  color: var(--ink);
}

.hint {
  text-align: center;
  color: var(--on-room-3);
  font-size: 0.84rem;
}

.hint + .hint {
  margin-top: 4px;
}

.handoff {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-bottom: 60px;
}

.handoff p {
  color: var(--on-room-2);
}

.handoff h1 {
  font-size: clamp(2.6rem, 12vw, 3.4rem);
  line-height: 1.05;
  margin: 6px 0 30px;
}

/* Result and fallback */

.panel {
  padding: 26px 24px 24px;
  border-radius: var(--r-card);
  background:
    radial-gradient(ellipse 90% 50% at 50% 0%, var(--lamp-bright) 0%, transparent 70%),
    linear-gradient(180deg, var(--lamp) 0%, var(--lamp-deep) 100%);
  color: var(--ink);
  box-shadow: var(--shadow-card);
}

.panel .lead {
  color: var(--ink-2);
  font-size: 0.95rem;
}

.panel h2 {
  margin: 10px 0 14px;
  font-size: clamp(2rem, 9vw, 2.5rem);
  line-height: 1.05;
}

.supporters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  margin-bottom: 20px;
  font-size: 0.95rem;
}

.supporters span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.facts {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 22px;
}

.facts div {
  padding: 12px 14px;
  border-radius: var(--r-control);
  background: rgba(42, 30, 35, 0.06);
}

.facts small {
  display: block;
  color: var(--ink-2);
  font-size: 0.8rem;
}

.facts strong {
  display: block;
  font-weight: 600;
  font-size: 1rem;
}

.panel .order {
  margin-top: 0;
  padding-top: 0;
}

.panel .note {
  margin-top: 18px;
  color: var(--ink-2);
  font-size: 0.86rem;
  line-height: 1.5;
}

.links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
}

.links a {
  flex: 1;
  display: grid;
  place-items: center;
  height: 48px;
  padding: 0 16px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--lamp);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
}

.links span {
  color: var(--ink-3);
  font-size: 0.86rem;
}

.after {
  display: flex;
  justify-content: center;
  padding: 24px 0 8px;
}

.plate-items {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 16px;
  margin: 0 0 20px;
  padding: 0;
  list-style: none;
}

.plate-items li {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-weight: 500;
  line-height: 1.35;
}

.plate-items li::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--chili);
  flex-shrink: 0;
  transform: translateY(-1px);
}

.panel .instructions {
  line-height: 1.55;
}

.waiting {
  flex: 1;
  justify-content: center;
  padding-bottom: 60px;
}

.waiting .roster {
  margin-top: 8px;
}

footer {
  padding: 28px 4px 0;
  text-align: center;
  color: var(--on-room-3);
  font-size: 0.82rem;
}

@media (min-width: 720px) {
  .shell {
    width: min(460px, 100%);
  }

  .topbar {
    height: 80px;
  }

  .stage {
    min-height: 540px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
  }
}

